import { useMemo, useState } from 'react';
import { useData, cmpOrderKey } from '../lib/data.js';
import { KindBadge } from './KindBadge.jsx';
import { UnitPill } from './UnitPill.jsx';
import { ActiveFilterStrip } from './ActiveFilterStrip.jsx';

// Middle pane: filtered, optionally-grouped list of result rows.
//
// Group modes:
//  - "none"     — flat, single empty-headed group, in the order `results`
//                 arrived (search-mode preserves score order)
//  - "category" — group by category label, alpha within
//  - "cluster"  — group by "${category} · ${group}"; within a category,
//                 bigger clusters first then alpha by key
//
// Score-ordered override:
//  When `searchMode === 'scored'`, the user has asked a question and
//  expects the most relevant hit at the top. Re-grouping into clusters
//  and then sorting each group alphabetically destroys that — typing
//  "pressure" then putting the result list into the Equilibrium cluster
//  buries every `*_pressure` row under `area_of_flux_surface` because
//  "a…" comes before "e…", and you see a row that only mentions
//  pressure in its long description above the row that IS pressure.
//  In score mode we therefore render the flat ordered list regardless
//  of `groupBy`. The toggle still shows the user's preferred grouping
//  for when they clear the query.
export function ResultsList({
  results,
  selected,
  onSelect,
  dense,
  groupBy,
  setGroupBy,
  query,
  searchTokens,
  searchMode,
  filters,
  setFilters,
}) {
  const { CATEGORIES } = useData();
  const scoreOrdered = searchMode === 'scored';
  const grouped = useMemo(() => {
    if (scoreOrdered || groupBy === 'none') return [['', results]];
    const catOf = (id) => CATEGORIES.find((c) => c.id === id)?.label || id;
    const map = new Map();
    for (const n of results) {
      const key =
        groupBy === 'category' ? catOf(n.category) : `${catOf(n.category)} · ${n.group}`;
      if (!map.has(key)) map.set(key, []);
      map.get(key).push(n);
    }
    const entries = [...map.entries()].map(([k, items]) => [
      k,
      items.slice().sort(cmpOrderKey),
    ]);
    if (groupBy === 'cluster') {
      entries.sort((A, B) => {
        const [ka, ia] = A;
        const [kb, ib] = B;
        const catA = ka.split(' · ')[0];
        const catB = kb.split(' · ')[0];
        if (catA !== catB) return catA.localeCompare(catB);
        if (ib.length !== ia.length) return ib.length - ia.length;
        return ka.localeCompare(kb);
      });
    } else {
      entries.sort((A, B) => A[0].localeCompare(B[0]));
    }
    return entries;
  }, [results, groupBy, CATEGORIES, scoreOrdered]);

  // Per-heading collapsed state. Clicking a group header toggles
  // visibility of its names. A single "Outline / Expand all" button
  // in the meta row flips every group at once.
  const [collapsedHeadings, setCollapsedHeadings] = useState(new Set());
  const toggleCollapse = (heading) => {
    setCollapsedHeadings((cur) => {
      const next = new Set(cur);
      next.has(heading) ? next.delete(heading) : next.add(heading);
      return next;
    });
  };

  const hasGroups = grouped.length > 0 && grouped[0][0] !== '';
  const allCollapsed = hasGroups
    && grouped.every(([h]) => collapsedHeadings.has(h));
  const collapseAll = () => {
    if (!hasGroups) return;
    if (allCollapsed) setCollapsedHeadings(new Set());
    else setCollapsedHeadings(new Set(grouped.map(([h]) => h)));
  };

  // Re-clicks of the active mode button reset the collapsed Set so
  // the gesture always reads as "fresh view". `useEffect` keyed on
  // groupBy would NOT fire on same-value clicks; an explicit reset
  // in the handler is the clearer contract.
  const handleSetGroupBy = (v) => {
    setCollapsedHeadings(new Set());
    setGroupBy(v);
  };

  const hasQuery = searchTokens && searchTokens.length > 0;

  return (
    <div className={`results-list dense-${dense}`}>
      <ActiveFilterStrip filters={filters} setFilters={setFilters} />
      {searchMode === 'fuzzy' && (
        <div className="results-fuzzy" title="No exact matches — showing subsequence matches against name">
          Fuzzy matches:
        </div>
      )}
      <div className="results-meta">
        <span>
          <strong>{results.length}</strong> {results.length === 1 ? 'name' : 'names'}
          {scoreOrdered && (
            <span className="results-sort-by" title="Sorted by search relevance — clear the query to re-enable grouping">
              {' · sorted by relevance'}
            </span>
          )}
        </span>
        {hasGroups && (
          <button
            className={`collapse-all ${allCollapsed ? 'is-collapsed' : ''}`}
            onClick={collapseAll}
            title={allCollapsed ? 'Expand all categories'
                                : 'Collapse to category outline'}
            aria-pressed={allCollapsed}
          >
            <svg width="11" height="11" viewBox="0 0 16 16" fill="none"
                 aria-hidden="true">
              <path d={allCollapsed ? 'M3 6L8 11L13 6' : 'M3 10L8 5L13 10'}
                    stroke="currentColor" strokeWidth="1.6"
                    strokeLinecap="round" strokeLinejoin="round" fill="none"/>
            </svg>
            <span>{allCollapsed ? 'Expand all' : 'Outline'}</span>
          </button>
        )}
        <div className="group-toggle" role="group" aria-label="Group results">
          {[
            ['none', 'A–Z'],
            ['category', 'Domain'],
            ['cluster', 'Concept'],
          ].map(([v, label]) => (
            <button
              key={v}
              className={groupBy === v ? 'on' : ''}
              onClick={() => handleSetGroupBy(v)}
              title={
                v === 'cluster'
                  ? 'Group by concept (locus or base quantity)'
                  : v === 'category'
                  ? 'Group by domain'
                  : 'Flat alphabetical'
              }
            >
              {label}
            </button>
          ))}
        </div>
      </div>
      {grouped.map(([heading, items]) => {
        const collapsed = collapsedHeadings.has(heading);
        return (
          <div key={heading}
               className={`result-group ${collapsed ? 'is-collapsed' : ''}`}>
            {heading && (
              <button
                type="button"
                className="result-group-head"
                onClick={() => toggleCollapse(heading)}
                aria-expanded={!collapsed}
                aria-controls={`group-body-${heading}`}
                title={collapsed ? 'Expand category' : 'Collapse category'}
              >
                <svg className="result-group-caret"
                     width="10" height="10" viewBox="0 0 12 12" fill="none"
                     aria-hidden="true">
                  <path d="M3 4.5L6 7.5L9 4.5"
                        stroke="currentColor" strokeWidth="1.6"
                        strokeLinecap="round" strokeLinejoin="round" fill="none"/>
                </svg>
                <span className="result-group-label">{heading}</span>
                <span className="result-group-count">{items.length}</span>
              </button>
            )}
            {!collapsed && (
              <div className="result-group-body" id={`group-body-${heading}`}>
                {items.map((n) => {
                  const lc = n.status || 'active';
                  return (
                    <button
                      key={n.name}
                      className={`result-row lifecycle-${lc} ${selected === n.name ? 'selected' : ''}`}
                      onClick={() => onSelect(n.name)}
                      title={lc !== 'active' ? `${n.name} — ${lc}` : undefined}
                    >
                      {/* Kind badge — visible at Comfortable and Compact;
                          dropped only at Dense where every pixel goes to the name. */}
                      {dense !== 'dense' && <KindBadge name={n} />}
                      <div className="result-main">
                        <div className="result-name-row">
                          <span className="result-name">{n.name}</span>
                          {/* Successor pointer — only rendered for SUPERSEDED names.
                              Deprecated entries are being retired with no committed
                              replacement, so we do not invent a "use this instead". */}
                          {lc === 'superseded' && n.superseded_by && dense !== 'dense' && (
                            <span
                              className="result-successor mono"
                              onClick={(e) => {
                                e.stopPropagation();
                                onSelect(n.superseded_by);
                              }}
                              title={`Open ${n.superseded_by}`}
                            >
                              <span className="result-successor-arrow" aria-hidden="true">→</span>
                              {n.superseded_by}
                            </span>
                          )}
                        </div>
                        {/* Description shown at Comfortable + Compact;
                            CSS clamps Compact to one line. */}
                        {dense !== 'dense' && (
                          <div className="result-desc">{n.short}</div>
                        )}
                      </div>
                      {dense !== 'dense' && (
                        <div className="result-meta">
                          <UnitPill unit={n.unit} />
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
      {results.length === 0 && (
        <div className="empty">
          <div className="empty-glyph">∅</div>
          <div>
            {hasQuery ? (
              <>No matches for «{query}»</>
            ) : (
              <>No names match these filters.</>
            )}
          </div>
          {hasQuery && (
            <div className="empty-tokens" aria-label="Parsed search tokens">
              <span className="empty-tokens-label">tokens parsed:</span>
              {searchTokens.map((t) => (
                <span key={t} className="empty-token mono">{t}</span>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
